"""Verified installed-mode update staging and elevated transaction launch."""
import ctypes
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import shutil
import subprocess
import tempfile
from urllib.parse import quote, urlsplit
from urllib.request import Request, urlopen
import uuid
import zipfile


MAX_PACKAGE = 8 * 1024**3
MAX_EXPANDED = 16 * 1024**3
ITEMS = {"EXPC-WLK.exe", "runtime", "app", "updater", "installed-layout.json"}
_READY_HANDSHAKE = None


def version(value):
    match = re.fullmatch(r"v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)", value)
    if not match:
        raise ValueError("Expected a stable semantic version")
    return tuple(int(part) for part in match.groups())


def _safe_member(name):
    if "\\" in name or ":" in name or name.startswith("/"):
        raise ValueError("Unsafe archive path")
    parts = PurePosixPath(name).parts
    if not parts or any(part in ("", ".", "..") or part.endswith((".", " ")) for part in parts):
        raise ValueError("Unsafe archive path")
    if parts[0] not in ITEMS:
        raise ValueError("Unexpected installed update path: " + name)
    if any(part.lower() in ("models", "user_settings.yaml", "vocabulary.db") for part in parts):
        raise ValueError("Update contains external data")
    return parts


def stage_archive(archive, expected_hash, expected_version, expected_profile, destination):
    archive, destination = Path(archive), Path(destination)
    with archive.open("rb") as stream:
        if hashlib.file_digest(stream, "sha256").hexdigest() != expected_hash:
            raise ValueError("SHA-256 mismatch")
    if destination.exists():
        raise ValueError("Stage must be new")
    with zipfile.ZipFile(archive) as package:
        files = [entry for entry in package.infolist() if not entry.is_dir()]
        names, total = set(), 0
        for entry in files:
            _safe_member(entry.filename)
            key = entry.filename.casefold()
            if key in names or (entry.external_attr >> 16) & 0o170000 == 0o120000:
                raise ValueError("Duplicate path or symbolic link")
            names.add(key)
            total += entry.file_size
        required = {
            "expc-wlk.exe", "runtime/pythonw.exe", "app/installed_boot.py",
            "updater/installedupdater.exe", "updater/config/release.json",
            "updater/config/package-profile.json", "installed-layout.json",
        }
        if not required <= names or total > MAX_EXPANDED or len(files) > 100000:
            raise ValueError("Incomplete or oversized installed update")
        release = json.loads(package.read(next(
            entry for entry in files if entry.filename.casefold() == "updater/config/release.json"
        )))
        profile = json.loads(package.read(next(
            entry for entry in files if entry.filename.casefold() == "updater/config/package-profile.json"
        )))
        if version(release["version"]) != version(expected_version):
            raise ValueError("Update version mismatch")
        if profile.get("variant") != expected_profile:
            raise ValueError("Update profile mismatch")
        destination.mkdir(parents=True)
        try:
            for entry in files:
                target = destination.joinpath(*_safe_member(entry.filename))
                target.parent.mkdir(parents=True, exist_ok=True)
                with package.open(entry) as source, target.open("xb") as output:
                    shutil.copyfileobj(source, output)
        except Exception:
            shutil.rmtree(destination)
            raise
    return destination


def _release_config():
    root = Path(os.environ["EXPC_WLK_METADATA_ROOT"])
    return json.loads((root / "config" / "release.json").read_text(encoding="utf-8"))


def check_latest(config=None, fetch=None):
    config = config or _release_config()
    repo = config.get("repository", "")
    if not repo or not re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+", repo):
        return {"status": "not_configured"}
    fetch = fetch or _fetch_metadata
    data = fetch(f"https://api.github.com/repos/{repo}/releases/latest")
    current, latest = version(config["version"]), version(data["tag_name"])
    if latest <= current:
        return {"status": "up_to_date" if latest == current else "older"}
    asset_name = f"EXPC-WLK-installed-{config['package_variant'].upper()}-v{data['tag_name'].lstrip('v')}.zip"
    assets = [asset for asset in data.get("assets", []) if asset.get("name") == asset_name]
    if len(assets) != 1:
        raise ValueError("Official installed update asset missing")
    asset = assets[0]
    if not re.fullmatch(r"sha256:[a-fA-F0-9]{64}", asset.get("digest", "")):
        raise ValueError("Installed update digest missing")
    return {"status": "available", "version": data["tag_name"].lstrip("v"),
            "url": asset["browser_download_url"], "sha256": asset["digest"][7:].lower(),
            "size": asset["size"], "profile": config["package_variant"]}


def _fetch_metadata(url):
    request = Request(url, headers={"Accept": "application/vnd.github+json",
                                    "User-Agent": "EXPC-WLK-installed-updater"})
    with urlopen(request, timeout=10) as response:
        return json.loads(response.read(2 * 1024**2 + 1))


def download(result, destination):
    request = Request(result["url"], headers={"User-Agent": "EXPC-WLK-installed-updater"})
    digest, received = hashlib.sha256(), 0
    with urlopen(request, timeout=20) as response, Path(destination).open("xb") as output:
        final = urlsplit(response.url)
        if final.scheme != "https" or final.hostname not in (
                "github.com", "release-assets.githubusercontent.com", "objects.githubusercontent.com"):
            raise ValueError("Unexpected update redirect")
        while chunk := response.read(1024**2):
            received += len(chunk)
            if received > result["size"] or received > MAX_PACKAGE:
                raise ValueError("Update exceeds published size")
            digest.update(chunk)
            output.write(chunk)
    if received != result["size"] or digest.hexdigest() != result["sha256"]:
        raise ValueError("Update integrity verification failed")


def prepare_update(result):
    work = Path(tempfile.mkdtemp(prefix="EXPC-WLK-installed-update-"))
    try:
        archive = work / "update.zip"
        download(result, archive)
        stage = stage_archive(archive, result["sha256"], result["version"],
                              result["profile"], work / "stage")
        archive.unlink()
        return work, stage
    except Exception:
        shutil.rmtree(work)
        raise


def launch_transaction(stage, launcher_pid, app_pid):
    stage = Path(stage).resolve()
    root = Path(os.environ["EXPC_WLK_INSTALL_ROOT"]).resolve()
    user_data = Path(os.environ["APPDATA"]) / "whisperkey"
    token = uuid.uuid4().hex
    receipt = user_data / ("installed-update-ready-" + token + ".json")
    helper = stage.parent / "InstalledUpdater.exe"
    shutil.copy2(root / "updater" / "InstalledUpdater.exe", helper)
    arguments = subprocess.list2cmdline([
        str(root), str(stage), str(receipt), str(launcher_pid), str(app_pid), token, "--quiet"
    ])
    result = ctypes.windll.shell32.ShellExecuteW(None, "runas", str(helper), arguments,
                                                 str(stage.parent), 0)
    if result <= 32:
        raise OSError("Failed to start elevated installed updater")
    return token


def offer_update(result, language, quit_app):
    ru = language == "ru"
    prompt = (("Скачать и установить обновление {version}?" if ru else
               "Download and install update {version}?").format(**result))
    if ctypes.windll.user32.MessageBoxW(None, prompt, "EXPC-WLK", 0x24) != 6:
        return
    _, stage = prepare_update(result)
    launch_transaction(stage, os.getppid(), os.getpid())
    quit_app()


def configure_ready(token, receipt, user_data=None):
    """Accept an explicit one-shot Ready handshake from the installed launcher."""
    global _READY_HANDSHAKE
    if not re.fullmatch(r"[a-f0-9]{32}", token or ""):
        raise ValueError("Invalid installed update token")
    root = Path(user_data) if user_data is not None else Path(os.environ["APPDATA"]) / "whisperkey"
    expected = (root / ("installed-update-ready-" + token + ".json")).resolve()
    supplied = Path(receipt).resolve()
    if supplied != expected:
        raise ValueError("Invalid installed update receipt path")
    _READY_HANDSHAKE = (token, expected)


def mark_ready():
    global _READY_HANDSHAKE
    handshake, _READY_HANDSHAKE = _READY_HANDSHAKE, None
    if handshake is None:
        return False
    token, path = handshake
    payload = json.dumps({"format": 1, "state": "ready", "token": token},
                         sort_keys=True, separators=(",", ":")) + "\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".tmp-" + uuid.uuid4().hex)
    try:
        temporary.write_text(payload, encoding="ascii")
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)
    return True
